  ('dried fruit', 'link', 'default', 2709195, false, 'USDA FNDDS "Dried fruit, NFS" is USDA''s own generic record (raisins 299, dried cranberries 308, apricots 241, dates 282 around it); the recipes list raisins, cranberries, apricots or dates'),
  ('fruit juice', 'link', 'default', 2709315, false, 'USDA FNDDS "Fruit juice, NFS" is USDA''s own generic record (orange 45, apple 46, grape 61 around it)'),
  ('ham hocks', 'link', 'default', 2705900, false, 'USDA FNDDS "Pork, ham hocks"'),
  ('raw banana', 'link', 'default', 910130323, false, 'UK CoFID "Plantain, green flesh, raw" (raw banana, kachcha kela, is the green cooking plantain; USDA ripe plantain raw is 123 kcal, CoFID green 117)'),
  ('borage', 'link', 'default', 170481, false, 'USDA SR Legacy "Borage, raw"'),
  ('carnitas', 'link', 'default', 2705864, false, 'USDA FNDDS "Pork, carnitas"'),
  ('cashew fruit', 'link', 'default', 910140060, false, 'UK CoFID "Cashew fruit, flesh only" (the fruit, not the nut)'),
  ('fonio', 'link', 'default', 2710829, false, 'USDA Foundation "Fonio, grain, dry, raw"'),
  ('hard cider', 'link', 'default', 2710621, false, 'USDA FNDDS "Hard cider" (SR Legacy and CNF agree at 56 kcal)'),
  ('haupia', 'link', 'default', 2710316, false, 'USDA FNDDS "Haupia"'),
  ('hollandaise sauce', 'link', 'default', 2710171, false, 'USDA FNDDS "Hollandaise sauce" (CNF butter sauce 430 kcal and the UK homemade recipe 717 show how much recipes differ; the USDA generic record is used)'),
  ('injera', 'link', 'default', 2707796, false, 'USDA FNDDS "Injera, Ethiopian bread"'),
  ('maple butter', 'link', 'default', 900006177, false, 'Canadian Nutrient File "Sweets, butter, maple" (maple butter / maple cream)'),
  ('mizithra', 'link', 'default', 361973, false, 'a real FoodData Central label of the product: 10 of the 11 US myzithra labels agree on 286 kcal per 100 g (all describe the aged, grating cheese; fresh myzithra is moister)'),
  ('pointed gourd', 'link', 'default', 910130277, false, 'owner decision wave 14: UK CoFID "Marrow, parwal, raw" (parwal is the pointed gourd)'),
  ('sev', 'link', 'default', 910170836, false, 'UK CoFID "Sev/ganthia, homemade" (the Indian chickpea-flour snack)'),
