  ('dried blueberries', 'relink', 'default', 168158, false, 'USDA SR Legacy "Blueberries, dried, sweetened" replaces a 13-nutrient label'),
  ('dried cherries', 'relink', 'default', 2709199, false, 'USDA FNDDS "Cherries, dried" replaces a 16-nutrient label'),
  ('dried pineapple', 'relink', 'default', 2709210, false, 'USDA FNDDS "Pineapple, dried" replaces a 16-nutrient label'),
  ('duck fat', 'relink', 'default', 900000447, false, 'Canadian Nutrient File "Animal fat, duck" replaces an 8-nutrient label'),
  ('dulce de leche', 'relink', 'default', 173461, false, 'USDA SR Legacy "Dulce de Leche" replaces a 15-nutrient label'),
  ('egg roll wrappers', 'relink', 'default', 172802, false, 'USDA SR Legacy "Wonton wrappers (includes egg roll wrappers)" replaces a 14-nutrient label'),
  ('garri', 'relink', 'default', 910110899, false, 'UK CoFID "Flour, gari (cassava flour)" (4 samples) replaces a 13-nutrient label'),
  ('guacamole', 'relink', 'default', 2709307, false, 'USDA FNDDS "Guacamole, NFS" replaces a 16-nutrient label'),
  ('hazelnut spread', 'relink', 'default', 168000, false, 'USDA SR Legacy "Chocolate-flavored hazelnut spread" replaces a 13-nutrient label'),
  ('mascarpone', 'relink', 'default', 910120490, false, 'UK CoFID "Cheese, Mascarpone" (8 samples) replaces a 12-nutrient label'),
  ('pico de gallo', 'relink', 'default', 2709737, false, 'USDA FNDDS "Salsa, pico de gallo" replaces a 13-nutrient label'),
  ('salsa verde', 'relink', 'default', 171824, false, 'USDA SR Legacy "Sauce, salsa, verde, ready-to-serve" replaces a 13-nutrient label'),
  ('sweet and sour sauce', 'relink', 'default', 174066, false, 'USDA SR Legacy "Sauce, sweet and sour, ready-to-serve" replaces a 19-nutrient label');

-- 2a. relink: the old default of the form becomes a non-default alternate (2c drops it when it is more than 25 percent / 20 kcal from the new record)
update ingredient_foods f set is_default = false, is_proxy = false from _w14 a, ingredients i
 where a.action = 'relink' and i.canonical_name = a.ingredient and f.ingredient_id = i.id and f.form = a.form and f.is_default and f.fdc_id <> a.new_fdc;
-- 2b. the new default (a food that is not in usda_foods on this database is skipped, and the gate below says so)
insert into ingredient_foods (ingredient_id, form, fdc_id, is_default, is_proxy)
select i.id, a.form, a.new_fdc, true, a.proxy from _w14 a join ingredients i on i.canonical_name = a.ingredient
 where exists (select 1 from usda_foods u where u.fdc_id = a.new_fdc)
on conflict (ingredient_id, form, fdc_id) do update set is_default = true, is_proxy = excluded.is_proxy;
update ingredients i set fdc_id = a.new_fdc from _w14 a
 where a.form = 'default' and i.canonical_name = a.ingredient and exists (select 1 from usda_foods u where u.fdc_id = a.new_fdc);
-- 2c. a non-default alternate that is far from the new default is dropped (a brand that disagrees with the record is not a brand of this food)
delete from ingredient_foods f using _w14 a, ingredients i, usda_food_nutrients nk, usda_food_nutrients ok
 where a.action = 'relink' and i.canonical_name = a.ingredient and f.ingredient_id = i.id and f.form = a.form and not f.is_default
   and nk.fdc_id = a.new_fdc and nk.nutrient_id = 1 and ok.fdc_id = f.fdc_id and ok.nutrient_id = 1
   and abs(ok.amount_per_100g - nk.amount_per_100g) > greatest(0.25 * nk.amount_per_100g, 20);
-- 2d. a recipe line that pinned a food the ingredient no longer links to goes back to the ingredient's default
update recipe_ingredients ri set fdc_id = null
  from _w14 a join ingredients i on i.canonical_name = a.ingredient
 where ri.ingredient_id = i.id and ri.fdc_id is not null
   and not exists (select 1 from ingredient_foods f where f.ingredient_id = i.id and f.fdc_id = ri.fdc_id);

-- 3. densities from the record's own volume portions (only where the ingredient has none)
update ingredients i set density_g_per_ml = v.d from (values
  ('dried fruit', 0.676),
  ('fruit juice', 1.048),
  ('ham hocks', 0.592),
  ('borage', 0.376),
  ('carnitas', 0.571),
  ('hard cider', 1.014),
  ('haupia', 0.9),
  ('hollandaise sauce', 1.082),
  ('injera', 0.287),
  ('simple syrup', 1.353),
  ('sorrel', 0.562),
  ('squash blossoms', 0.139),
  ('textured vegetable protein', 0.397),
  ('agave syrup', 1.165),
  ('dried blueberries', 0.676),
  ('dried cherries', 0.676),
  ('dried pineapple', 0.676),
  ('dulce de leche', 1.285),
  ('guacamole', 1.014),
  ('hazelnut spread', 1.251),
  ('pico de gallo', 1.014),
  ('salsa verde', 1.014),
  ('sweet and sour sauce', 1.183)
) as v(ing, d)
where i.canonical_name = v.ing and i.density_g_per_ml is null;
-- 4. household weights (USDA portions of the record)
insert into ingredient_portions (ingredient_id, form, unit_id, grams_per_unit, source, note)
select i.id, v.form, u.id, v.g, v.src, v.note from (values
  ('ham hocks', 'default', 'each', 85.0, 'usda', 'USDA household weight'),
  ('haupia', 'default', 'piece', 23.0, 'usda', 'USDA household weight'),
  ('injera', 'default', 'each', 127.0, 'usda', 'USDA household weight'),
  ('dried pineapple', 'default', 'slice', 8.0, 'usda', 'USDA household weight')
) as v(ing, form, unit, g, src, note)
join ingredients i on i.canonical_name = v.ing
left join units u on u.name = v.unit
where v.unit = 'each' or u.id is not null
on conflict (ingredient_id, form, (coalesce(unit_id, 0))) do nothing;
-- 5. sweetened foods: added sugars are a share of the record's carbohydrate (the schema returns 0 for an ingredient that is not listed)
insert into added_sugar_ingredients (ingredient_id, fraction, note)
select i.id, v.f, v.n from (values
  ('simple syrup', 1.0, 'sweetener: sugar dissolved in water (FNDDS total sugars 45.7 of 45.6 g carbohydrate)'),
  ('maple butter', 1.0, 'sweetener: maple syrup counts as added sugar (CNF carbohydrate is all sugar)'),
  ('haupia', 0.63, 'FNDDS reports 14.7 g total sugars of 23.5 g carbohydrate; coconut milk, sugar and cornstarch, so the sugars are treated as added')
) as v(ing, f, n) join ingredients i on i.canonical_name = v.ing
on conflict (ingredient_id) do nothing;
commit;
